{
  "questions": [
    {
      "question_id": "q1",
      "question": "What does the fermentation liquid look like at the intended measurement point?"
    },
    {
      "question_id": "q2",
      "question": "What kind of reported result do you need for glucose concentration and viable biomass?"
    },
    {
      "question_id": "q3",
      "question": "Is there a known fluorescent compound, marker or reference relationship linked to glucose concentration or viable biomass?"
    },
    {
      "question_id": "q4",
      "question": "Is the result intended for research, a pilot line or production?"
    },
    {
      "question_id": "q5",
      "question": "Which reference methods, if any, provide comparison values for glucose concentration and viable biomass?"
    },
    {
      "question_id": "q6",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit, for either target?"
    }
  ],
  "plan": {
    "objective": "Test whether the proposed optical methods can report glucose concentration and viable biomass against independent reference values.",
    "samples_and_states": [
      {
        "text": "Collect representative fermentation samples spanning client-agreed glucose concentrations, viable biomass levels and process states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Use time-matched independent glucose assays and viable biomass reference measurements, rather than turbidity alone, as comparison values.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Acquire spectra using the specified NIR, Raman and UV-Vis probe arrangements at a measurement point agreed with you.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare separately calibrated models for each method against the glucose concentration and viable biomass references.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Validate each target's predictions on independent fermentation runs excluded from calibration.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Use target-specific criteria agreed with you before testing to make separate go/no-go decisions on independent material.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Direct fluorescence reporting of either target is not demonstrated by the supplied information.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify outputs, liquid appearance, fluorescence basis, application stage and criteria.",
      "Collect representative fermentation samples across agreed process states.",
      "Obtain time-matched glucose and viable biomass reference values.",
      "Set up probes and compare calibrated optical methods.",
      "Validate target-specific predictions on independent fermentation runs.",
      "Apply client-agreed criteria to separate target-specific go/no-go decisions."
    ]
  },
  "decision_basis": [
    {
      "text": "Base each target's decision on prediction errors against reference measurements on independent fermentation material, using criteria agreed with you before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
